/* PART 30 — 3D weapon models + model-rendered item icons */
/* Guns (pistol/shotgun/smg/sniper x iron/golden/diamond) + the Bow (which is now,
   canonically, a crossbow). CC0: Quaternius Ultimate Gun Pack, KayKit Adventurers. The skateboard and
   gadget meshes are third-party too (credits and licences: THIRD_PARTY.md). Entry 14 (the snail) is a plain box build made
   with tools/art/meshes/box_pack.mjs (specs in tools/art/meshes/specs/).
   Packed data: p=Int8 xyz x200 b64, i=Uint16 b64, v=Uint8 palette idx b64,
   pal=[[rgbInt,tintable],...]. Item icons for tools+weapons are software-rendered
   straight from this geometry so the hotbar matches the held model. */
const WPN3D={"pistol":{"n":1209,"p":"","i":"","v":"","pal":[[4210752,1],[3158064,0],[5263456,1]]},"shotgun":{"n":416,"p":"","i":"","v":"","pal":[[3158064,0],[3158064,1],[6312000,0],[4210752,1],[5259328,0]]},"smg":{"n":778,"p":"","i":"","v":"","pal":[[3158064,1],[4210752,1],[3158064,0]]},"sniper":{"n":804,"p":"","i":"","v":"","pal":[[3158064,0],[5263440,1],[3158064,1],[4128,0]]},"bow":{"n":546,"p":"","i":"","v":"","pal":[[9478304,0],[9474208,0],[8417376,0],[7364704,0],[8421520,0],[7364688,0],[6316112,0],[6312016,0],[6312000,0],[5263424,0],[11583680,0],[11579584,0],[9478320,0],[12632256,0],[8425616,0],[10510400,0],[9457728,0],[11563088,0],[10510416,0],[11558992,0],[10530992,0],[12636368,0],[13684944,0],[12632272,0],[10526896,0]]},"skate":{"n":516,"p":"","i":"","v":"","pal":[[12624000,0],[11571312,0],[11575408,0],[12623984,0],[3158080,0],[3158064,0],[10522736,0],[9465936,0],[9470048,0],[8417360,0],[10518624,0],[4210752,0],[2105376,0],[1052688,0],[8425600,0],[10526880,0],[13684944,0],[12636352,0],[9474192,0],[14737632,0],[15790304,0],[15790320,0],[14741728,0],[13689040,0],[12632240,0],[11579568,0],[13684928,0],[12632256,0],[14737616,0],[11583664,0],[11579552,0],[5263440,0],[6316128,0],[9474176,0],[10530976,0],[8421504,0],[9478288,0]]},"gd_dj":{"n":91,"p":"","i":"","v":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAEBAQEAAAAAAAABAQEBAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAQEBAQEBAQEBAQEBAQEBAQ==","pal":[[12619888,0],[8413264,0]]},"gd_jet":{"n":2119,"p":"","i":"","v":"","pal":[[4218976,0],[8425632,0],[13689056,0],[8409152,0],[16777215,0],[15745072,0],[16752640,0],[16773184,0],[9486416,0],[16732192,0]]},"gd_grap":{"n":262,"p":"","i":"","v":"","pal":[[4210752,0]]},"gd_glide":{"n":260,"p":"","i":"","v":"","pal":[[2105376,0],[16736256,0],[16639,0],[16777215,0]]},"gd_mag":{"n":414,"p":"","i":"","v":"","pal":[[16777215,0],[14692400,0]]},"gd_tramp":{"n":438,"p":"","i":"","v":"","pal":[[3158064,0],[24752,0],[28848,0],[32976,0],[32960,0],[28864,0],[24736,0],[2105376,0],[11579568,0],[10526880,0],[9474192,0],[12628144,0],[8421504,0],[10522768,0],[11575456,0],[12632256,0],[9470080,0]]},"gd_pig":{"n":1349,"p":"","i":"","v":"","pal":[[5259312,0],[4206656,0],[8421504,0]]},"snail":{"n":384,"p":"","i":"","v":"","pal":[[13676672,0],[13680800,0],[10518608,0],[8409120,0]]}};
const WPN_KEY=['pistol','shotgun','smg','sniper'];
const WPN_YAW={pistol:-Math.PI/2,shotgun:Math.PI/2,smg:Math.PI/2,sniper:Math.PI/2,bow:0,skate:Math.PI/2};
function gunIdParts(id){if(id>=200&&id<212){const n=id-200;return {m:(n/4)|0,t:n%4};}return null;}
function b64bytes(s){
  const A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let pad=0;while(s[s.length-1-pad]==='=')pad++;
  const out=new Uint8Array((s.length/4)*3-pad);let o=0;
  for(let i=0;i<s.length;i+=4){
    const b=(A.indexOf(s[i])<<18)|(A.indexOf(s[i+1])<<12)|((A.indexOf(s[i+2])&63)<<6)|(A.indexOf(s[i+3])&63);
    out[o++]=b>>16&255;if(o<out.length)out[o++]=b>>8&255;if(o<out.length)out[o++]=b&255;
  }
  return out;
}
const W3RAW={};
function wpnRaw(key){
  if(W3RAW[key])return W3RAW[key];
  const d=WPN3D[key];
  const pb=b64bytes(d.p),ib=b64bytes(d.i);
  const P=new Float32Array(d.n*3);
  for(let i=0;i<d.n*3;i++){const v=pb[i];P[i]=(v<128?v:v-256)/200;}
  return W3RAW[key]={P,I:new Uint16Array(ib.buffer),V:b64bytes(d.v),pal:d.pal,n:d.n};
}
const W3GEO={};
function wpnGeo(key,mi){ /* mi -1 = untinted (bow), else GUNMAT index */
  const ck=key+'_'+mi;
  if(W3GEO[ck])return W3GEO[ck];
  const d=wpnRaw(key);
  let tint=null;
  if(mi>=0){const cc=parseInt(GUNMAT[mi].col.slice(1),16);tint=[(cc>>16&255)/255,(cc>>8&255)/255,(cc&255)/255];}
  const col=new Float32Array(d.n*3);
  for(let i=0;i<d.n;i++){
    const e=d.pal[d.V[i]],ci=e[0];
    let r=(ci>>16&255)/255,g=(ci>>8&255)/255,b=(ci&255)/255;
    if(e[1]&&tint){const l=0.35+0.9*(r+g+b)/3;r=Math.min(1,tint[0]*l);g=Math.min(1,tint[1]*l);b=Math.min(1,tint[2]*l);}
    col[i*3]=r;col[i*3+1]=g;col[i*3+2]=b;
  }
  const g3=new THREE.BufferGeometry();
  g3.setAttribute('position',new THREE.Float32BufferAttribute(d.P,3));
  g3.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
  g3.setIndex(new THREE.BufferAttribute(d.I,1));
  g3.computeVertexNormals();
  W3GEO[ck]=g3;return g3;
}
/* group scaled to s world-units long, muzzle facing -Z */
function mkWpn3D(id,s){
  let key=null,mi=-1;
  const gp=gunIdParts(id);
  if(gp){key=WPN_KEY[gp.t];mi=gp.m;}
  else if(id===IT.BOW)key='bow';
  else if(id===IT.SKATE)key='skate';
  else if(DEFS[id]&&DEFS[id].gadget){
    const gk='gd_'+DEFS[id].gadget;
    if(WPN3D[gk])key=gk;
    else{const g2=mkGadgetProc(DEFS[id].gadget);g2.scale.set(s,s,s);return g2;}
  }
  if(!key)return null;
  const g=new THREE.Group();
  const m=new THREE.Mesh(wpnGeo(key,mi),T3MAT);
  m.scale.set(s,s,s);m.rotation.y=WPN_YAW[key]||0;
  g.add(m);g.isT3D=true;
  return g;
}
/* 16px item icon rendered from the model data (painter's algorithm) */
function draw3DIcon(c,kind,m,t){
  c.clearRect(0,0,16,16);
  let P,I,COL,proj;
  if(kind==='tool'){
    const d=TOOL3D[TOOL3D_KEY[t]];P=d.p;I=d.i;
    const cc=parseInt(TOOLMAT[m].col.slice(1),16),tr=cc>>16&255,tg=cc>>8&255,tb=cc&255;
    COL=i=>{const bc=d.c[i],r=bc>>16&255,g=bc>>8&255,b=bc&255;
      if(d.h[i]){const l=0.45+0.75*(r+g+b)/765;return [Math.min(255,tr*l),Math.min(255,tg*l),Math.min(255,tb*l)];}
      return [r,g,b];};
    proj=i=>[8+P[i*3]*13,15.5-P[i*3+1]*14.5,P[i*3+2]];
  }else{
    const key=kind==='bow'?'bow':WPN_KEY[t];
    const d=wpnRaw(key);P=d.P;I=d.I;
    let tint=null;
    if(kind==='gun'){const cc=parseInt(GUNMAT[m].col.slice(1),16);tint=[cc>>16&255,cc>>8&255,cc&255];}
    COL=i=>{const e=d.pal[d.V[i]],ci=e[0];let r=ci>>16&255,g=ci>>8&255,b=ci&255;
      if(e[1]&&tint){const l=0.35+0.9*(r+g+b)/765;r=Math.min(255,tint[0]*l);g=Math.min(255,tint[1]*l);b=Math.min(255,tint[2]*l);}
      return [r,g,b];};
    if(kind==='bow')proj=i=>[8-P[i*3+2]*12,8+P[i*3]*12,P[i*3+1]];
    else{const fx=key==='pistol'?-1:1;proj=i=>[8+P[i*3]*fx*15,9-P[i*3+1]*15,P[i*3+2]*fx];}
  }
  const tris=[];
  for(let k=0;k<I.length;k+=3){
    const a=proj(I[k]),b2=proj(I[k+1]),c2=proj(I[k+2]);
    tris.push([(a[2]+b2[2]+c2[2])/3,a,b2,c2,I[k]]);
  }
  tris.sort((x,y)=>x[0]-y[0]);
  for(const tr2 of tris){
    const a=tr2[1],b2=tr2[2],c2=tr2[3],col=COL(tr2[4]);
    const ar=(b2[0]-a[0])*(c2[1]-a[1])-(b2[1]-a[1])*(c2[0]-a[0]);
    const f=ar<0?1.0:0.8;
    c.fillStyle='rgb('+((col[0]*f)|0)+','+((col[1]*f)|0)+','+((col[2]*f)|0)+')';
    c.beginPath();c.moveTo(a[0],a[1]);c.lineTo(b2[0],b2[1]);c.lineTo(c2[0],c2[1]);c.closePath();c.fill();
  }
}

